"""Loader for ``backend/data/ps02_episode_map.yaml`` (generated by scripts/build_episode_map.py)."""

from __future__ import annotations

from functools import lru_cache
from pathlib import Path
from typing import Any

import yaml

from sentinel.datagen.types import EpisodeAssignment

DEFAULT_PATH = Path(__file__).resolve().parents[2] / "data" / "ps02_episode_map.yaml"


def _read(path: Path | str | None) -> dict[str, Any]:
    return yaml.safe_load(Path(path or DEFAULT_PATH).read_text())


def load_episode_map(path: Path | str | None = None) -> list[EpisodeAssignment]:
    out = []
    for e in _read(path)["episodes"]:
        e = {**e, "benign_evidence": tuple(e.get("benign_evidence") or ())}
        out.append(EpisodeAssignment(**e))
    return out


@lru_cache(maxsize=1)
def _default() -> tuple[EpisodeAssignment, ...]:
    return tuple(load_episode_map())


def by_anchor(ts: str, service: str, metric: str) -> EpisodeAssignment:
    for a in _default():
        if (a.anchor_ts, a.service, a.metric) == (ts, service, metric):
            return a
    raise KeyError((ts, service, metric))


def incidents() -> list[EpisodeAssignment]:
    return [a for a in _default() if a.kind == "incident"]


def negatives() -> list[EpisodeAssignment]:
    return [a for a in _default() if a.kind == "negative"]


def events() -> list[dict[str, Any]]:
    """Synthetic deploy events cited by N4 rows (EVENT_COLUMNS keys)."""
    return list(_read(None).get("events") or [])
